#!/bin/bash
# Minneapolis run registry adds, part 1 of 10 (no set -e: refused duplicates do not stop the run). Source ./.env first. Run each part once; re-runs add duplicates.
A=0;R=0;REF=""
add(){ if python3 registry.py add "$@"; then A=$((A+1)); else R=$((R+1)); REF="$REF ${2}"; fi; }
add --slug shine-on-minneapolis-kickoff-block-party-and-tree-lighting-mn --name 'Shine On Minneapolis Kickoff Block Party and Tree Lighting' --city Minneapolis --cc mn --url https://www.minneapolis.org/calendar/shine-on-minneapolis/ --date 2026-11-27 --status live --confirm-new || true
add --slug minneapolis-christmas-light-tour-on-a-heated-holiday-trolley-mn --name 'Minneapolis Christmas Light Tour on a Heated Holiday Trolley' --city Minneapolis --cc mn --url https://minneapolistrolleytours.com/holiday-light-ride/ --date 2026-12-01 --status live --confirm-new || true
add --slug home-alone-in-concert-with-the-minnesota-orchestra-minneapolis-mn --name 'Home Alone in Concert with the Minnesota Orchestra' --city Minneapolis --cc mn --url https://www.minnesotaorchestra.org/tickets/calendar/movies-music/home-alone-in-concert-with-the-minnesota-orchestra --date 2026-12-11 --status live --confirm-new || true
add --slug santas-storytime-trolley-at-minnesota-streetcar-museum-minneapolis-mn --name 'Santa'"'"'s Storytime Trolley at Minnesota Streetcar Museum' --city Minneapolis --cc mn --url https://trolleyride.org/product/santas-storytime-trolley-saturday-november-28/ --date 2026-11-28 --status live --confirm-new || true
add --slug loyce-houltons-nutcracker-fantasy-at-the-state-theatre-minneapolis-mn --name 'Loyce Houlton'"'"'s Nutcracker Fantasy at the State Theatre' --city Minneapolis --cc mn --url https://hennepinarts.org/events/loyce-houltons-nutcracker-fantasy-2026 --date 2026-12-12 --status live --confirm-new || true
add --slug winter-solstice-celebration-at-the-american-swedish-institute-minneapolis-mn --name 'Winter Solstice Celebration at the American Swedish Institute' --city Minneapolis --cc mn --url https://asimn.org/experience/festivals/winter-solstice/ --date 2026-12-18 --status live --confirm-new || true
add --slug holidays-on-hennepin-kids-events-in-uptown-gingerbread-minneapolis-mn --name 'Holidays on Hennepin Kids Events in Uptown: Gingerbread Spectacular and Cookie Decorating with Santa' --city Minneapolis --cc mn --url https://www.holidaysonhennepin.com/calendar --date 2026-11-28 --status live --confirm-new || true
add --slug minnesota-cookie-creations-at-mill-city-museum-minneapolis-mn --name 'Minnesota Cookie Creations at Mill City Museum' --city Minneapolis --cc mn --url https://www.mnhs.org/events/63278021292 --date 2026-12-05 --status live --confirm-new || true
add --slug santas-train-shop-and-caboose-rides-at-jackson-street-roundhouse-saint-paul-mn --name 'Santa'"'"'s Train Shop and Caboose Rides at Jackson Street Roundhouse' --city 'Saint Paul' --cc mn --url https://trainride.org/santas-train-shop/ --date 2026-12-05 --status live --confirm-new || true
add --slug minnesota-merry-market-at-the-state-fairgrounds-north-end-falcon-heights-mn --name 'Minnesota Merry Market at the State Fairgrounds North End Event Center' --city 'Falcon Heights' --cc mn --url https://www.homespunevents.com/minnesotamerrymarket --date 2026-12-05 --status live --confirm-new || true
echo "added $A, refused $R"; [ "$R" -gt 0 ] && echo "refused slugs:$REF"
exit 0
